internals.subSchema = Joi.object({
    filter: Joi.func(),                                             // function (path, update, options, next), where options: { credentials, params }
    onSubscribe: Joi.func(),                                        // function (socket)
    onUnsubscribe: Joi.func(),                                      // function (socket)
    auth: Joi.object({
